def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Fast counters over full history.
    my_c = my_d = opp_c = opp_d = 0
    cc = 0
    for i in range(n):
        a, b = history[i]
        if a == 'C':
            my_c += 1
            if b == 'C':
                cc += 1
            else:
                pass
        else:
            my_d += 1
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1

    # Recent window stats.
    w = 8 if n >= 8 else n
    rec_opp_d = 0
    rec_my_d = 0
    rec_cc = 0
    for i in range(n - w, n):
        a, b = history[i]
        if b == 'D':
            rec_opp_d += 1
        if a == 'D':
            rec_my_d += 1
        if a == 'C' and b == 'C':
            rec_cc += 1

    last_my, last_opp = history[-1]
    remaining = 100 - n

    # Opponent never defected: exploit, but keep some cooperation to avoid
    # destroying a potentially conditionally cooperative partner late.
    if opp_d == 0:
        if n < 70:
            # Mostly defect against unconditional cooperators, but seed cooperation.
            if n < 12:
                return 'C'
            return 'D'
        return 'D'

    # Opponent almost never defected (very forgiving likely).
    if opp_d * 10 <= n:
        if last_opp == 'D':
            # Forgive a single isolated defection to preserve cooperation.
            if rec_opp_d <= 1:
                return 'C'
            return 'D'
        # Defect more as match progresses to exploit forgiving opponents.
        if remaining <= 6:
            return 'D'
        if n >= 20 and rng.random() < 0.25 + 0.5 * (n / 100.0):
            return 'D'
        return 'C'

    # Opponent heavily defective: exploit with rare probes for a cooperative shift.
    if opp_d * 3 >= n * 2:
        if last_opp == 'C':
            # Reward a cooperative move, but only briefly if they remain defective.
            if opp_c * 4 >= n:
                return 'C'
            if remaining <= 3:
                return 'D'
            return 'C' if rec_opp_d <= 1 else 'D'
        if remaining <= 4:
            return 'D'
        # Rare probe: cooperate occasionally to test for responsiveness.
        return 'C' if (n % 11 == 0 or rng.random() < 0.04) else 'D'

    # Middling defection rate. Use a forgiving, retaliatory policy that
    # recovers quickly (key vs TFT-style probes) but punishes sustained D.
    if last_opp == 'D':
        # Rapid forgiveness if isolated and opponent otherwise cooperative.
        if rec_opp_d <= 1 and opp_d * 4 <= n:
            return 'C'
        # If we are in a mutual-defection rut, sometimes break out with C.
        if last_my == 'D' and rec_my_d >= 2:
            if rng.random() < 0.35:
                return 'C'
            return 'D'
        # Punish, but consider probing for recovery periodically.
        if remaining <= 5:
            return 'D'
        if rec_opp_d >= 3:
            return 'D'
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    if remaining <= 2:
        # Final rounds: grab points unless opponent is highly cooperative.
        if opp_d == 0:
            return 'D'
        if opp_c * 10 >= n * 9:
            return 'C'
        return 'D'

    if remaining <= 8:
        if opp_c * 10 >= n * 8:
            # Mostly cooperate with trustworthy partner, occasional selfish.
            return 'D' if rng.random() < 0.25 else 'C'
        return 'D'

    # Normal regime: maintain cooperation, probe sparingly to detect exploiters.
    if rec_cc >= w - 1 and opp_d * 5 <= n:
        # Strong mutual cooperation run: stay mostly cooperative.
        if rng.random() < 0.04:
            return 'D'
        return 'C'

    # If we defected recently, return to cooperation to re-establish CC.
    if rec_my_d >= 2:
        return 'C'

    if rng.random() < 0.06:
        return 'D'
    return 'C'
